function pushChat(room, player, text) {
  const clean = String(text || '').trim().slice(0, 160);
  if (!clean) return;
  room.chat.push({ from: player ? player.name : 'system', id: player ? player.id : null, text: clean, at: Date.now() });
  if (room.chat.length > 60) room.chat.splice(0, room.chat.length - 60);
}

function chat(player, msg) {
  const room = player.room;
  if (!room) return;
  if (!['lobby', 'discuss', 'end', 'tally'].includes(room.phase)) {
    return send(player, { t: 'error', msg: 'Chat is open during the lobby and discussion.' });
  }
  pushChat(room, player, msg.text);
  broadcast(room);
}

function leave(player) {
  const room = player.room;
  player.connected = false;
  if (!room) return;
  const wasHost = room.hostId === player.id;
  const impostorLeft = player.isImpostor && ['reveal', 'clues', 'discuss', 'vote', 'tally', 'guess'].includes(room.phase);

  room.players = room.players.filter((p) => p !== player);
  player.room = null;

  if (room.players.length === 0) {
    clearTimer(room);
    rooms.delete(room.code);
    return;
  }
  if (wasHost) {
    const next = room.players.find((p) => p.connected);
    if (next) room.hostId = next.id;
  }
  pushChat(room, null, `${player.name} left`);

  if (impostorLeft && room.phase !== 'end') {
    endGame(room, 'crew', 'The impostor disconnected.');
    return;
  }
  if (['reveal', 'clues', 'discuss', 'vote'].includes(room.phase)) {
    if (connected(room).length < MIN_PLAYERS) {
      endGame(room, 'crew', 'Not enough players left.');
      return;
    }
    if (room.phase === 'reveal' && connected(room).every((p) => p.ready)) beginClues(room);
    else if (room.phase === 'clues') {
      const cur = currentTurnPlayer(room);
      if (!cur) setPhase(room, 'discuss', DISCUSS_MS);
    } else if (room.phase === 'vote' && connected(room).every((p) => p.voted)) {
      setPhase(room, 'tally', TALLY_MS);
      setTimeout(() => { if (room.phase === 'tally') tallyVotes(room); }, TALLY_MS + 50);
    }
  }
  broadcast(room);
}

server.listen(PORT, () => {
