  const code = String(msg.code || '').trim().toUpperCase();
  const room = rooms.get(code);
  if (!room) return send(player, { t: 'error', msg: 'No room with that code.' });

  // reconnect: the same browser is reclaiming its seat after a refresh/drop
  const existing = msg.resume ? room.players.find((p) => p.id === msg.resume) : null;
  if (existing && existing !== player) {
    const oldWs = existing.ws;
    existing.ws = player.ws;
    existing.connected = true;
    if (oldWs && oldWs !== player.ws) {
      oldWs.removeAllListeners();
      try { oldWs.close(); } catch { /* ignore */ }
    }
    // swap the fresh connection object onto the saved seat
    Object.assign(player, existing);
    const fresh = room.players.filter((p) => p !== existing);
    room.players = fresh.concat(player);
    player.room = room;
    player.connected = true;
    send(player, { t: 'you', id: player.id, code });
    broadcast(room);
    return;
  }

  if (room.players.filter((p) => p.connected).length >= MAX_PLAYERS) {
    return send(player, { t: 'error', msg: 'That room is full.' });
